      const pts = d ? this._pts(i, d) : [], vs = pts.map((p) => p[1]), dg = Number.isFinite(Number(s.digits)) ? Number(s.digits) : 1, u = units[i];
      // value now: the entity's state, or for an attribute series the point nearest to now
